function readCasePrice(value){
 var normalized=String(value).trim().replace(/\s/g,'').replace(',','.');
 if(!/^\d+(?:\.\d{0,2})?$/.test(normalized))return NaN;
 var price=Number(normalized);
 return Number.isFinite(price)&&price>0&&price<=1e9?Math.round(price*100)/100:NaN;
}
