var creatingSupportPayment=false,pollingSupportPayment=false,shownSupportReceipts=new Set();
function supportPendingKey(){return 'brainup-support:'+NET.id}
async function pollSupportPayment(id,attempts){if(pollingSupportPayment)return;pollingSupportPayment=true;try{for(var i=0;i<(attempts||1);i++){var response=await fetch('/api/support?id='+encodeURIComponent(id),{cache:'no-store',signal:AbortSignal.timeout(7000)}),result=await response.json();if(!response.ok||!result.ok)break;if(result.status==='paid'){if(!shownSupportReceipts.has(id)){shownSupportReceipts.add(id);try{localStorage.removeItem(supportPendingKey())}catch(error){}if(result.creditedBU&&!NET.busy){try{var snapshot=await NET.request('state',{});NET.adopt(snapshot);render()}catch(error){}}openModal('<h3 class="bu-mt">'+(result.creditedBU?'Баланс пополнен':'Спасибо за поддержку!')+'</h3><p>Оплата '+result.stars+' Stars подтверждена Telegram.'+(result.creditedBU?' Начислено '+fmt(result.creditedBU)+' BU.':'')+'</p><button class="bu-btn" data-pa="close">Закрыть</button>')}return}if(result.status==='refunded'){try{localStorage.removeItem(supportPendingKey())}catch(error){}toast('Оплата возвращена');return}if(i+1<(attempts||1))await new Promise(function(resolve){setTimeout(resolve,1200)})}}catch(error){toast('Подтверждение оплаты задерживается. Его можно проверить после возвращения в приложение.')}finally{pollingSupportPayment=false}}
async function startSupportPayment(){
 if(creatingSupportPayment)return;
 var tg=window.Telegram&&Telegram.WebApp;
 if(!tg||!tg.initData||typeof tg.openInvoice!=='function')return toast('Откройте оплату внутри Telegram');
 var stars=Number(TP.stars);
 if(!Number.isSafeInteger(stars)||stars<1||stars>10000)return toast('Укажите целое число от 1 до 10 000 Stars');
 creatingSupportPayment=true;
 var button=document.querySelector('[data-tp2="stars"]');
 if(button){button.disabled=true;button.setAttribute('aria-busy','true')}
 function release(){creatingSupportPayment=false;if(button&&button.isConnected){button.disabled=false;button.removeAttribute('aria-busy')}}
 var id=crypto.randomUUID();
 try{
  var response=await fetch('/api/support',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:id,stars:stars}),signal:AbortSignal.timeout(15000)}),result=await response.json();
  if(!response.ok||!result.ok)throw Error(result.error||'Не удалось создать счёт');
  if(typeof result.invoiceUrl!=='string'||!result.invoiceUrl.startsWith('https://t.me/'))throw Error('Не удалось получить счёт Telegram');
  try{localStorage.setItem(supportPendingKey(),id)}catch(error){}
  tg.openInvoice(result.invoiceUrl,function(status){
   release();
   if(status==='paid'){toast('Проверяем подтверждение Telegram…');pollSupportPayment(id,12)}
   else if(status==='cancelled'){try{localStorage.removeItem(supportPendingKey())}catch(error){}toast('Оплата отменена')}
   else if(status==='failed'){try{localStorage.removeItem(supportPendingKey())}catch(error){}toast('Оплата не прошла. Попробуйте ещё раз.')}
   else{toast('Ожидаем подтверждение Telegram…');pollSupportPayment(id,3)}
  });
 }catch(error){release();toast(error.message)}
}
function restoreSupportPayment(){if(!NET.ready||document.hidden||pollingSupportPayment)return;try{var id=localStorage.getItem(supportPendingKey());if(id)pollSupportPayment(id,1)}catch(error){}}
window.addEventListener('focus',restoreSupportPayment);document.addEventListener('visibilitychange',restoreSupportPayment);setTimeout(restoreSupportPayment,3000);
